357	export function formatPrintTime(seconds: number): string {
358	  const minutes = Math.round(seconds / 60);
359	  if (minutes < 60) return `~${minutes} min`;
360	  return `~${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
361	}
362	
363	export function formatGrams(grams: number): string {
364	  return `${grams < 10 ? Math.round(grams * 10) / 10 : Math.round(grams)} g`;
365	}
366	
367	export function formatCost(cost: number, currency: string): string {
368	  if (currency) {
369	    try {
370	      return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(cost);
371	    } catch {
372	      // An unknown regional code does not make the native amount disappear.
373	    }
374	  }
375	  return `cost ${cost.toFixed(2)}`;
376	}
377	
378	export function formatMoment(value: string | undefined): string {
379	  if (!value) return '';
380	  const date = new Date(value);
381	  if (Number.isNaN(date.getTime())) return value;
382	  return date.toLocaleString(undefined, {
383	    month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false,
384	  });
385	}
