399	export function estimateView(context: WorkspaceContext): EstimateView {
400	  const plate = context.plates.find((item) => item.active);
401	  const view: EstimateView = {
402	    heading: '', metrics: [], cost: '', plate: plate?.name ?? '', description: '', status: 'none', sliced: !!plate?.sliced,
403	  };
404	  if (!plate) return { ...view, description: 'Estimate unavailable' };
405	  const estimate = plate.estimate;
406	  const scoped = (text: string) => plate.name ? `${text} · ${plate.name}` : text;
407	  const metrics: EstimateView['metrics'] = [];
408	  if (estimate && (estimate.timeAvailable ?? estimate.printTimeSeconds > 0))
409	    metrics.push({ icon: 'clock', text: formatPrintTime(estimate.printTimeSeconds) });
410	  if (estimate && (estimate.materialAvailable ?? estimate.materialGrams > 0))
411	    metrics.push({ icon: 'package', text: formatGrams(estimate.materialGrams) });
412	  if (plate.estimateStatus === 'recomputing')
413	    return { ...view, status: 'recomputing', heading: 'Time & material estimates recomputing…',
414	      description: scoped('Settings confirmed') };
415	  if (metrics.length === 0)
416	    return { ...view, description: scoped(plate.sliced ? 'Estimate unavailable' : 'Not sliced yet · estimates unavailable') };
417	  const cost = estimate && estimate.materialCost !== null && estimate.materialCost >= 0.005
418	    ? formatCost(estimate.materialCost, context.currency) : '';
419	  if (plate.estimateStatus === 'stale')
420	    return { ...view, status: 'stale', heading: 'Previous estimates · not current', metrics, cost };
421	  return { ...view, status: 'current', metrics, cost };
422	}
