424	export interface Finding { title: string; detail?: string; facts?: string[]; }
425	
426	export function deterministicAttention(context: WorkspaceContext): Finding[] {
427	  const review = context.printerReview;
428	  if (!review) return [];
429	  const priority: Record<string, number> = { filament: 0, nozzle: 1, model: 2, plate: 3 };
430	  const noun: Record<string, string> = { filament: 'material', nozzle: 'nozzle', model: 'printer', plate: 'build plate' };
431	  const when = formatMoment(review.observed?.observedAt);
432	  return [...review.mismatches].sort((a, b) => (priority[a.what] ?? 4) - (priority[b.what] ?? 4)).flatMap((mismatch) => {
433	    const thing = noun[mismatch.what] ?? 'printer setup';
434	    if (mismatch.source === 'device') {
435	      if (!when) return [];
436	      const facts = [`Setup: ${mismatch.configured}`, `Printer last reported: ${mismatch.observed}`, `Reported ${when}`];
437	      if (review.observed?.connection) facts.push(`Printer is ${review.observed.connection} now`);
438	      return [{ title: `Last reported ${thing} differs`,
439	        detail: `Setup uses ${mismatch.configured}. Printer last reported ${mismatch.observed}.`, facts }];
440	    }
441	    return [{ title: `Confirmed ${thing} differs`,
442	      detail: `Setup uses ${mismatch.configured}. You confirmed ${mismatch.observed}.`,
443	      facts: [`Setup: ${mismatch.configured}`, `You confirmed: ${mismatch.observed}`] }];
444	  });
445	}
