447	export function recentAgentChange(changes: ChangeInfo[] | undefined, now: number): ChangeInfo[] {
448	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
449	  const last = log.at(-1);
450	  if (!last || last.actor !== 'agent' || (last.kind !== 'setting' && last.kind !== 'step')) return [];
451	  const made = Date.parse(last.createdAt);
452	  if (!Number.isFinite(made) || now - made >= RECENT_CHANGE_MS || now < made) return [];
453	  let start = log.length - 1;
454	  while (start > 0 && log[start - 1].actor === 'agent' && log[start - 1].afterId === last.afterId &&
455	    (log[start - 1].kind === 'setting' || log[start - 1].kind === 'step')) start -= 1;
456	  return log.slice(start);
457	}
458	
459	export function handEdits(changes: ChangeInfo[] | undefined): ChangeInfo[] {
460	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
461	  let start = log.length;
462	  while (start > 0 && log[start - 1].actor === 'person' && log[start - 1].kind !== 'restore') start -= 1;
463	  const net = new Map<string, ChangeInfo>();
464	  for (const change of log.slice(start))
465	    if (change.kind === 'setting') net.set(change.key || change.label, change);
466	  return [...net.values()];
467	}
