482	export function presetsLine(context: WorkspaceContext, title: string): string {
483	  const process = context.printer.process.trim();
484	  if (!process) return '';
485	  const filaments = context.setupIdentity?.filaments ?? [];
486	  const first = (filaments[0]?.preset || context.printer.filament).trim();
487	  const filament = first ? `${shortPreset(first)}${filaments.length > 1 ? ` +${filaments.length - 1}` : ''}` : '';
488	  const parts = title === process ? [filament] : [shortPreset(process), filament];
489	  return parts.filter(Boolean).join(' · ');
490	}
