509	// What the card and the setup page both say about themselves: their label,
510	// their one state, their title. Conversation status outranks live activity: a
511	// saved card is never working, whatever the active chat happens to be doing.
512	export function setupPresentation(context: WorkspaceContext, options: SetupPresentationOptions = {}) {
513	  const historical = !!options.historical;
514	  const working = !!options.working && !historical;
515	  const estimate = estimateView(context);
516	  const intent = context.setupIntent.trim();
517	  const title = intent || context.printer.process.trim();
518	  // Nothing vouches for this setup but the preset the person picked: no agent
519	  // is configured, or the host read no settings to compare with it.
520	  const noAgent = !historical && options.agentAvailable === false;
521	  if (noAgent || (!historical && !context.appliedSetup && !intent))
522	    return { label: 'Preset fallback', state: noAgent ? 'No agent' : null as ReactNode, title: context.printer.process.trim(),
523	      estimate, justChanged: [], edited: [], editedByYou: false, outOfDate: false, live: true, fallback: true, noAgent };
524	  const justChanged = historical ? [] : recentAgentChange(options.changes, options.now ?? Date.now());
525	  const edited = historical || working || justChanged.length > 0 ? [] : handEdits(options.changes);
526	  // "Edited by you" needs a setup the agent had a hand in; without one a
527	  // hand edit is simply how the project was made.
528	  const agentManaged = !!intent || (options.changes ?? []).some((change) => change.actor === 'agent');
529	  const editedByYou = edited.length > 0 && agentManaged;
530	  // Out of date stands the card down: it drops the accent, as a saved card
531	  // does, because it no longer vouches for the numbers under it.
532	  const outOfDate = estimate.status === 'stale' && !working && justChanged.length === 0 && !editedByYou;
533	  const saved = formatMoment(options.savedAt);
534	  const label = options.sent ? 'Saved sliced snapshot' : historical || outOfDate ? 'Earlier setup' : 'Setup summary';
535	  const state: ReactNode = historical
536	    ? options.sent ? 'Sliced & sent' : estimate.status === 'stale' ? 'Out of date'
537	      : saved ? <><span className="jp-icon jp-icon-clock" aria-hidden="true" />Saved {saved}</> : null
538	    : working ? 'Agent working' : justChanged.length > 0 ? 'Updated'
539	    : estimate.status === 'recomputing' ? 'Confirmed' : editedByYou ? 'Edited by you'
540	    : outOfDate ? 'Out of date' : estimate.status === 'none' && !estimate.sliced ? 'Not sliced' : 'Current';
541	  return { label, state, title, estimate, justChanged, edited, editedByYou, outOfDate, live: !historical && !outOfDate,
542	    fallback: false, noAgent: false };
543	}
