545	function Metrics({ estimate }: { estimate: EstimateView }) {
546	  return <div className="current-setup-metrics">
547	    {estimate.metrics.map((metric) => <span className="current-setup-metric" key={metric.icon}>
548	      <span className={`jp-icon jp-icon-${metric.icon}`} aria-hidden="true" />{metric.text}</span>)}
549	    {estimate.plate && <span className="current-setup-metric">
550	      <span className="jp-icon jp-icon-grid-3x3" aria-hidden="true" />{estimate.plate}</span>}
551	    {estimate.cost && <span className="current-setup-metric">{estimate.cost}</span>}
552	  </div>;
553	}
