555	function Attention({ findings }: { findings: Finding[] }) {
556	  const [open, setOpen] = useState(false);
557	  if (findings.length === 0) return null;
558	  const first = findings[0];
559	  const reviewable = findings.length > 1 || (first.facts ?? []).length > 0;
560	  const subject = findings.length > 1 ? plural(findings.length, 'finding', 'findings')
561	    : first.title.replace(/^(Last reported|Confirmed) | differs$/g, '');
562	  return <>
563	    <div className="current-setup-attention">
564	      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />{first.title}</p>
565	      {first.detail && <p className="current-setup-line">{first.detail}</p>}
566	      {reviewable && <button type="button" className="current-setup-link" aria-expanded={open} onClick={() => setOpen(!open)}>
567	        Review {subject}</button>}
568	      {open && <ul className="current-setup-findings">{findings.map((finding, index) => <li key={index}>
569	        {findings.length > 1 && <strong>{finding.title}</strong>}
570	        {(finding.facts ?? []).map((fact) => <span key={fact}>{fact}</span>)}
571	      </li>)}</ul>}
572	    </div>
573	    <hr className="current-setup-divider" />
574	  </>;
575	}
