577	export function SetupCard({ context, working: busy = false, historical = false, savedAt, agentAvailable = true,
578	  changes, now = Date.now(), estimateBefore, sent, attention = [], onCompute, onUndo, onViewSetup }: SetupCardProps) {
579	  if (!context) return null;
580	  // A saved card is never working, whatever the active chat happens to be
581	  // doing.
582	  const working = busy && !historical;
583	  const ariaLabel = historical ? 'Earlier setup — saved with this conversation' : 'Current setup';
584	  const presentation = setupPresentation(context, { historical, working, agentAvailable, changes, now, sent, savedAt });
585	
586	  if (presentation.fallback) {
587	    const { estimate, title } = presentation;
588	    return <section className="current-setup current-setup--live" data-testid="current-setup" aria-label={ariaLabel}>
589	      <div className="current-setup-header"><span className="current-setup-label">{presentation.label}</span>
590	        {presentation.state && <span className="current-setup-state">{presentation.state}</span>}</div>
591	      {title && <h2 className="current-setup-title" title={title}>{title}</h2>}
592	      {presentation.noAgent ? <p className="current-setup-line">No agent configured · using the selected preset.</p>
593	        : estimate.metrics.length > 0 ? <Metrics estimate={estimate} />
594	        : <p className="current-setup-line">{estimate.description}</p>}
595	    </section>;
596	  }
597	
598	  const { estimate, justChanged, edited, editedByYou, outOfDate } = presentation;
599	  // The plan's headline in every state the card has: the state label and the
600	  // notices say how far the card can be trusted. With no plan pinned there is
601	  // no line at all.
602	  const headline = context.planHeadline.trim();
603	  const objects = overrideObjectCount(context);
604	  const presets = presetsLine(context, presentation.title);
605	
606	  const withheld = editedByYou && estimate.status === 'stale';
607	  const heading = withheld ? '' : estimate.heading ? estimate.heading : estimate.metrics.length === 0 ? ''
608	    : sent ? 'Saved pre-slice estimates' : working ? 'Last confirmed estimates' : '';
609	  const description = withheld ? (estimate.plate ? `Estimate unavailable for these edits · ${estimate.plate}`
610	    : 'Estimate unavailable for these edits') : estimate.description;
611	  const canCompute = !historical && !working && !!onCompute && estimate.status === 'none';
612	  // What the card adds for the minute a change is new. The settings the
613	  // agent changed are not listed: the thread's change rows under its turn
614	  // name them, and the setup page lists every difference. A project step is
615	  // named here, and it is the one thing Orca can undo: its undo takes the top
616	  // of its own stack, and a preset edit is not on it.
617	  const last = justChanged.at(-1);
618	  const step = !working && last?.kind === 'step' ? last : undefined;
619	  const undoable = !!onUndo && !!step && context.history.canUndo;
620	  const plate = context.plates.find((item) => item.active);
621	  const after = plate?.estimate;
622	  const estimateDelta = justChanged.length > 0 && estimateBefore && after && estimate.status === 'current' &&
623	    (estimateBefore.printTimeSeconds !== after.printTimeSeconds || estimateBefore.materialGrams !== after.materialGrams)
624	    ? `Estimate: ${estimatePair(estimateBefore)} → ${estimatePair(after)}` : '';
625	  const named = edited.slice(0, 2).map((change) => `${change.label} ${change.to || 'none'}`);
626	  const editedText = edited.length > 2 ? `${named.join(', ')} and ${plural(edited.length - 2, 'more setting', 'more settings')}`
627	    : named.join(' and ');
628	  const findings = [...deterministicAttention(context), ...attention];
629	
630	  return <section className={presentation.live ? 'current-setup current-setup--live' : 'current-setup'}
631	    data-testid="current-setup" aria-label={ariaLabel} aria-busy={working || undefined}>
632	    <div className="current-setup-header"><span className="current-setup-label">{presentation.label}</span>
633	      {presentation.state && <span className="current-setup-state">{presentation.state}</span>}</div>
634	    {presentation.title && <h2 className="current-setup-title" title={presentation.title}>{presentation.title}</h2>}
635	    {presets && <p className="current-setup-line current-setup-line--single" title={presets}>{presets}</p>}
636	    {headline && <p className="current-setup-strategy">{headline}</p>}
637	    {objects > 0 && <p className="current-setup-note">
638	      {plural(objects, 'object with overrides', 'objects with overrides')}</p>}
639	    {heading && <p className="current-setup-heading">{heading}</p>}
640	    {!withheld && estimate.metrics.length > 0 && <Metrics estimate={estimate} />}
641	    {description && <p className="current-setup-line">{description}</p>}
642	    {sent && estimate.metrics.length > 0 && <p className="current-setup-line">Actual time &amp; material unavailable.</p>}
643	    {canCompute && <button type="button" className="current-setup-link" onClick={onCompute}>Compute estimates</button>}
644	    <hr className="current-setup-divider" />
645	    {working && <><p className="current-setup-line">Agent is applying and evaluating changes…<br />
646	      Shown settings remain the last confirmed setup.</p><hr className="current-setup-divider" /></>}
647	    {!working && (step || estimateDelta) && <>
648	      {step && <p className="current-setup-line">{step.label || 'Object settings changed'}</p>}
649	      {estimateDelta && <p className="current-setup-line">{estimateDelta}</p>}
650	      {undoable && <button type="button" className="current-setup-link" onClick={() => onUndo!(step!.seq)}>Undo</button>}
651	      <hr className="current-setup-divider" />
652	    </>}
653	    {outOfDate && <><div className="current-setup-attention">
654	      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />
655	        {historical ? 'These estimates were already out of date when saved.' : 'Estimates no longer match the current project.'}</p>
656	      {plate?.invalidatedBy && <p className="current-setup-line">{plate.invalidatedBy}</p>}
657	      {!historical && onCompute && <button type="button" className="current-setup-link" onClick={onCompute}>
658	        Refresh setup &amp; recompute</button>}
659	    </div><hr className="current-setup-divider" /></>}
660	    {editedByYou && <><p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
661	      <span>You set {editedText} outside the agent. Your current settings are preserved.</span></p>
662	      <hr className="current-setup-divider" /></>}
663	    <Attention findings={findings} />
664	    <button type="button" className="current-setup-link" onClick={onViewSetup}>All settings</button>
665	    {historical && <><hr className="current-setup-divider" />
666	      {sent && <p className="current-setup-sent">{[formatMoment(sent.at), sent.printer && `sent to ${sent.printer}`]
667	        .filter(Boolean).join(' · ')}</p>}
668	      <p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
669	        <span>{sent ? 'Saved snapshot.' : 'Saved with this chat.'} The canvas shows your current project.</span></p>
670	    </>}
671	  </section>;
672	}
