  border-radius: var(--radius-full);
  color: var(--text-secondary);
  font: var(--font-metadata);
  letter-spacing: 0.04em;
}

/* Agent setup. The screens replace the dock body in place, so they reuse
   .pane-state's metrics and only add the card, the provider tabs, and the
   key row. */
/* The setup screens are the only pane states taller than the dock: a diff, a
   command and an error banner can all be on screen at once. They scroll, so
   the actions at the bottom stay reachable in a short window. */
.pane-state.setup {
  justify-content: flex-start;
  align-self: stretch;
  min-height: 0;
  overflow-y: auto;
}

.setup-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  width: 100%;
  padding: 16px;
  border-radius: var(--radius-large);
  background: var(--surface-selected);
}

.setup-card-head {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
}

.setup-card-head h1 {
  flex: 1;
  font: var(--font-section);
  margin: 0;
}

.setup-card p {
  margin: 0;
  color: var(--text-secondary);
}

button.primary.wide {
  width: 100%;
}

button.wide {
  width: 100%;
}

.setup-eyebrow {
  margin: 8px 0 0;
  font: var(--font-metadata);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.setup-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 8px 0;
  border: none;
  border-top: 1px solid var(--border-subtle);
  border-radius: 0;
  background: transparent;
  color: var(--text-primary);
  text-align: left;
  cursor: pointer;
}

.setup-row:hover:enabled,
.setup-row:active:enabled {
  background: transparent;
  border: none;
  border-top: 1px solid var(--border-subtle);
}

.setup-row:disabled {
  color: var(--action-disabled-text);
  cursor: default;
}

/* The provider switch is the design system's Segmented Control: a subtle
   track holding equal segments, the chosen one filled with action/primary. */
.setup-tabs {
  display: flex;
  box-sizing: border-box;
  width: 100%;
  height: var(--segmented-height);
  padding: var(--segmented-padding);
  border: var(--segmented-border-width) solid var(--border-subtle);
  border-radius: var(--segmented-radius);
  background: var(--surface-subtle);
}

.setup-tab {
  flex: 1;
  height: var(--segmented-segment-height);
  padding: var(--segmented-segment-padding-y) var(--segmented-segment-padding-x);
  border: none;
  border-radius: var(--segmented-radius);
  background: transparent;
  font: var(--font-label);
  color: var(--text-primary);
  cursor: pointer;
}

.setup-tab:hover:enabled,
.setup-tab:active:enabled {
  border: none;
}

.setup-tab.selected {
  background: var(--action-primary);
  color: var(--action-primary-text);
}

.setup-tab.selected:hover:enabled {
  background: var(--action-primary);
}

.setup-tab:disabled {
  color: var(--action-disabled-text);
  cursor: default;
}

/* The key field is the design system's Field/Secret: one bordered control,
   with the key (or its hint) and the links that act on it inside it. */
.setup-key {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: var(--field-height);
  padding: 0 var(--field-padding-x);
  border-radius: var(--radius-small);
  background: var(--surface-canvas);
  box-shadow: inset 0 0 0 1px var(--border-subtle);
}

/* The field, not the input inside it, draws the focus ring. */
.setup-key:has(.setup-key-input:focus-visible) {
  box-shadow: inset 0 0 0 2px var(--border-focus);
}

/* A saved key is read-only: shown, never edited, on a filled field. */
.setup-key--saved {
  background: var(--surface-subtle);
}

.setup-key--rejected {
  box-shadow: inset 0 0 0 1px var(--status-danger);
}

/* A key is code. */
.setup-key-input {
  flex: 1;
  min-width: 0;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--text-primary);
  font: var(--font-code);
}

.setup-key-input:focus,
.setup-key-input:focus-visible {
  outline: none;
}

.setup-key-input::placeholder {
  font: var(--font-body);
  color: var(--text-secondary);
}

.setup-key-hint {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font: var(--font-code);
  color: var(--text-primary);
}

.setup-key button.link.setup-key-remove,
.setup-key button.link.setup-key-remove:hover:enabled,
.setup-key button.link.setup-key-remove:active:enabled {
  color: var(--status-danger);
}

.setup-key-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font: var(--font-label-bold);
  color: var(--status-success);
}

.setup-key-status--rejected {
  color: var(--status-danger);
}

.setup-card p.setup-key-note {
  font: var(--font-label);
}

.setup-keeps {
  font: var(--font-label);
  color: var(--text-secondary);
}

.setup-actions button.link.setup-cancel,
.setup-actions button.link.setup-cancel:hover:enabled,
.setup-actions button.link.setup-cancel:active:enabled {
  color: var(--text-primary);
}

.setup-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  width: 100%;
}

.setup-result {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font: var(--font-label);
  color: var(--text-secondary);
}

.setup-result.ok {
  color: var(--status-success);
}

.setup-result.error {
  color: var(--status-danger);
}

/* One-time confirmation that the setup the user just completed worked. */
.setup-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-subtle);
  color: var(--status-success);
  font: var(--font-label);
}

.setup-banner.warning {
  color: var(--status-warning);
}

.setup-banner-text {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.setup-tool-list {
  width: 100%;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-medium);
  overflow: hidden;
  background: var(--surface-canvas);
}

/* 8px vertical padding on a Body line makes the 36px menu row. */
.setup-tool-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  font: var(--font-body);
  cursor: pointer;
}

.setup-tool-row:last-child {
  border-bottom: none;
}

.setup-tool-copy {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex: 1;
  min-width: 0;
}

.setup-tool-name {
  display: flex;
  align-items: baseline;
  gap: 4px;
  min-width: 0;
}

.setup-tool-sub {
  color: var(--text-secondary);
}

.setup-detected,
.setup-missing {
  flex: 0 0 auto;
  font: var(--font-label);
}

.setup-detected {
  color: var(--status-success);
}

.setup-missing {
  color: var(--text-secondary);
}

.setup-command {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  width: 100%;
  padding: 12px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-medium);
  background: var(--surface-subtle);
}

/* Deliberately the UI face, not the technical one: these blocks are copy
   the user reads, and the surrounding card already frames them. */
.setup-command pre,
.setup-error-details pre,
.setup-advanced pre {
  flex: 1;
  min-width: 0;
  margin: 0;
  font: var(--font-body);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.setup-advanced {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  width: 100%;
  margin-top: auto;
}

.setup-path {
  width: 100%;
  margin: 0;
  padding: 8px 12px;
  border-radius: var(--radius-small);
  background: var(--surface-subtle);
  font: var(--font-label);
  overflow-wrap: anywhere;
}

.setup-diff {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.setup-diff-before,
.setup-diff-after {
  margin: 0;
  padding: 8px 12px;
  border-radius: var(--radius-small);
  background: var(--surface-subtle);
  font: var(--font-body);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.setup-diff-after {
  border-left: 3px solid var(--status-success);
}

/* Stands in for the "before" block on a first connection, where there is no
   prior entry to show. */
.pane-state .setup-diff-absent {
  width: 100%;
  margin: 0;
  padding: 8px 12px;
  border-radius: var(--radius-small);
  background: var(--surface-subtle);
  font: var(--font-label);
}

.setup-progress {
  width: 100%;
  height: 6px;
  border-radius: var(--radius-full);
  background: var(--surface-subtle);
  overflow: hidden;
}

.setup-progress span {
  display: block;
  height: 100%;
  background: var(--status-danger);
}

.setup-kicker {
  display: flex;
  align-items: center;
  gap: 8px;
  font: var(--font-label-bold);
  color: var(--status-success);
}

.setup-expect {
  margin: 0;
  padding-left: 20px;
  color: var(--text-secondary);
  font: var(--font-body);
}

.setup-error {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--status-danger);
  border-radius: var(--radius-small);
  color: var(--status-danger);
}

.setup-error p {
  margin: 4px 0 0;
  color: var(--status-danger);
}

.setup-error-inline {
  color: var(--status-danger);
}

/* The one slot an error may occupy: directly above the buttons of whichever
   screen produced it, leaving the command or the diff visible behind it. */
.setup-error-slot {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  width: 100%;
}

/* The same disclosure as .setup-advanced, without its bottom-anchoring: this
   one belongs to the banner directly above it. */
.setup-error-details {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  width: 100%;
}

.setup-error .link {
  margin-top: 4px;
}

/* The consent question, weighted above the paragraphs around it. */
.pane-state .setup-consent {
  font: var(--font-body-bold);
  color: var(--text-primary);
}

/* An instruction for the user running the command by hand; grouped with the
   command box above it rather than with the footnote below. */
.setup-manual {
  margin-top: -8px;
}

