input.content:
/* Agent setup. The screens replace the dock body in place, so they reuse
   .pane-state's metrics and add the chooser card and the screen titles; the
   rows inside are the shared Agent connection rows below. */
/* The setup screens are the only pane states taller than the dock: a diff, a
   command and an error banner can all be on screen at once. They scroll, so
   the actions at the bottom stay reachable in a short window. */
.pane-state.setup {
  justify-content: flex-start;
  align-self: stretch;
  min-height: 0;
  overflow-y: auto;
}

.setup-card {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
  padding: 16px;
  border-radius: var(--radius-medium);
  background: var(--surface-subtle);
}

.setup-card-head {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
}

.setup-card-head h1 {
  flex: 1;
  font: var(--font-section);
  margin: 0;
}

.setup-card p {
  margin: 0;
  font: var(--font-body-small);
  color: var(--text-secondary);
}

button.primary.wide {
  width: 100%;
}

button.wide {
  width: 100%;
}

.setup-eyebrow {
  margin: 8px 0 0;
  font: var(--font-metadata);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

/* A screen's title is its way back: the chevron and the name, one target. */
.pane-state .setup-title {
  margin: 0;
  font: var(--font-section);
}

.setup-back {
  gap: 4px;
  padding: 0;
  border: 0;
  font: inherit;
  color: var(--text-primary);
  text-align: left;
}

.setup-back:hover:enabled {
  border-color: transparent;
}

.setup-back .jp-icon {
  width: var(--setup-card-icon-size);
  height: var(--setup-card-icon-size);
}

/* The two ways for people who already have an AI, under the account. */
.setup-ways {
  display: flex;
  flex-direction: column;
  padding-top: 12px;
  box-shadow: inset 0 1px 0 0 var(--border-subtle);
}

.setup-card p.setup-ways-title {
  padding-bottom: 4px;
  font: var(--font-label-bold);
  text-transform: uppercase;
}

.setup-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 8px 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: var(--text-primary);
  font: var(--font-body);
  text-align: left;
  cursor: pointer;
}

.setup-row:hover:enabled,
.setup-row:active:enabled {
  background: transparent;
  border: none;
}

.setup-row .jp-icon {
  width: var(--setup-card-icon-size);
  height: var(--setup-card-icon-size);
  color: var(--text-secondary);
}

.pane-state p.setup-footnote {
  margin-top: auto;
  font: var(--font-label);
}

.setup-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  width: 100%;
}

/* One-time confirmation that the setup the user just completed worked:
   a status line, so only its glyph carries the status color. */
.setup-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px 8px 16px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-subtle);
  color: var(--text-primary);
  font: var(--font-label-bold);
}

.setup-banner > .jp-icon {
  width: var(--setup-card-icon-size);
  height: var(--setup-card-icon-size);
  color: var(--status-success);
}

.setup-banner.warning > .jp-icon {
  color: var(--status-warning);
}

.setup-banner-text {
  flex: 1;
  min-width: 0;
}

.setup-banner button.icon {
  width: var(--button-icon-compact-width);
  height: var(--button-icon-compact-height);
}

/* The Agent connection rows (canvas "Agent/Account Row", "Agent/Provider
   Row", "Agent/Tool Row"), shared by Agent setup and Preferences › Agent.
   A group is a short intro, rows divided by a hairline, and a footnote. */
.agent-group {
  display: flex;
  flex-direction: column;
  width: 100%;
}

.agent-group-head {
  display: flex;
  flex-direction: column;
  padding-bottom: 8px;
}

.agent-group-title,
.agent-account-title {
  margin: 0;
  font: var(--font-body-bold);
  color: var(--text-primary);
}

.pane-state p.agent-group-intro,
p.agent-group-intro {
  margin: 0;
  font: var(--font-body-small);
  color: var(--text-secondary);
}

.agent-group-foot {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 12px;
  padding-top: 12px;
  box-shadow: inset 0 1px 0 0 var(--border-subtle);
}

.agent-row {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px 0;
  box-shadow: inset 0 1px 0 0 var(--border-subtle);
}

.agent-row-line,
.agent-account {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
}

/* The account's button drops under its text in a narrow dock. */
.agent-account {
  flex-wrap: wrap;
}

.agent-row-copy {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.agent-row-name {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px;
  font: var(--font-body);
  color: var(--text-primary);
}

.agent-row-detail {
  font: var(--font-body-small);
  color: var(--text-secondary);
}

.agent-row-status {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  font: var(--font-label);
  color: var(--text-secondary);
}

.agent-row-status .jp-icon,
.agent-row-action .jp-icon {
  width: var(--setup-card-icon-size);
  height: var(--setup-card-icon-size);
}

.agent-row-status--saved .jp-icon { color: var(--status-success); }
.agent-row-status--sessionOnly { color: var(--text-primary); }
.agent-row-status--sessionOnly .jp-icon { color: var(--status-warning); }
.agent-row-status--rejected { color: var(--status-danger); }

/* A key's hint is code, and always at full contrast: it is what tells two
   keys apart. */
.agent-key-hint,
.agent-key-keeps code {
  font: var(--font-code);
  color: var(--text-primary);
}

.agent-row-actions {
  flex: 0 0 auto;
  display: flex;
  gap: 8px;
}

/* The design system's Button/Secondary, drawn with an inset ring so it keeps
   its size whatever the hover does. */
.agent-row-action {
  flex: 0 0 auto;
  gap: var(--button-secondary-icon-gap);
  padding: var(--button-secondary-padding);
  border: 0;
  border-radius: var(--radius-small);
  box-shadow: inset 0 0 0 1px var(--border-subtle);
  color: var(--text-primary);
  font: var(--font-body-small);
  white-space: nowrap;
}

.agent-row-action:hover:enabled {
  background: var(--surface-subtle);
}

.agent-row-action:disabled {
  color: var(--action-disabled-text);
}

.agent-row-action--danger,
.agent-row-action--danger:disabled {
  box-shadow: inset 0 0 0 1px var(--status-danger);
  color: var(--status-danger);
}

.agent-row-action--danger:disabled {
  opacity: 0.4;
}

.agent-key-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.agent-key-label {
  font: var(--font-label);
  color: var(--text-secondary);
}

/* Field/Secret, tall enough to hold the Paste link inside it. The field, not
   the input, draws the ring. */
.agent-key-field {
  display: flex;
  align-items: center;
  gap: 8px;
  height: var(--provider-row-field-height);
  padding: 0 4px 0 var(--field-padding-x);
  border-radius: var(--radius-small);
  background: var(--surface-canvas);
  box-shadow: inset 0 0 0 1px var(--border-subtle);
}

